import { computed, defineComponent, h } from 'vue';
import { aspectRatioStyleKeys, getAspectRatioPadding } from '../lib/core';
import styles from './aspect-ratio.module.scss';

export const AspectRatio = defineComponent({
	name: 'AspectRatio',
	props: {
		ratio: { type: Number, default: 1 },
	},
	setup(props, { slots, attrs }) {
		const paddingTop = computed(() => `${getAspectRatioPadding(props.ratio)}%`);

		return () =>
			h(
				'div',
				{
					...attrs,
					'data-slot': 'aspect-ratio',
					class: [styles[aspectRatioStyleKeys.root], attrs.class],
					style: [attrs.style, { paddingTop: paddingTop.value }],
				},
				[h('div', { class: styles[aspectRatioStyleKeys.content] }, slots.default?.())],
			);
	},
});

export default AspectRatio;

@use '../../../styles/variables/colors' as *;

// AspectRatio 根容器：通过 padding-top 撑起高度
.root {
	position: relative;
	width: 100%;
}

// 内容容器：绝对定位占满
.content {
	position: absolute;
	inset: 0;
	display: flex;
	align-items: center;
	justify-content: center;
}
